import ast; import sys; from pathlib import Path; from common.meta.extension.check_package_contract import check_single_package, discover_packages; REPO = Path(__file__).resolve().parents[2]; LEDGER = REPO / 'apps/backend/src/ledger'; _BACKEND_ROOT = str(REPO / 'apps' / 'backend'); sys.path.insert(0, _BACKEND_ROOT) if _BACKEND_ROOT not in sys.path else None
def _imported_modules(path: Path) -> set[str]: mods: set[str] = set(); [mods.add(node.module) if isinstance(node, ast.ImportFrom) and node.module else mods.update((a.name for a in node.names)) if isinstance(node, ast.Import) else None for node in ast.walk(ast.parse(path.read_text(encoding='utf-8')))]; return mods
def test_ledger_converges_by_layer():
    assert (LEDGER / 'base/types/entry.py').exists(); assert (LEDGER / 'base/types/errors.py').exists(); assert (LEDGER / 'base/validators.py').exists(); assert (LEDGER / 'extension/post.py').exists(); assert (LEDGER / 'extension/repository.py').exists(); assert (LEDGER / 'data/balance.py').exists(); assert not (LEDGER / 'types').exists(); assert not (LEDGER / 'ops').exists(); assert not (LEDGER / 'store').exists(); exports = (LEDGER / '__init__.py').read_text(encoding='utf-8')
    for name in ('Entry', 'Leg', 'post_entry', 'journal_command_target', 'calculate_account_balance'): assert name in exports, f'ledger must export {name}'
def test_ledger_processing_converges_by_layer():
    base = LEDGER / 'base/processing.py'; ext = LEDGER / 'extension/processing.py'; assert base.exists(), 'processing pure core must live in base/processing.py'; assert ext.exists(), 'processing verbs must live in extension/processing.py'; base_src = base.read_text(encoding='utf-8')
    for name in ('class ProcessingAccount', 'class TransferPair', 'def detect_transfer_pattern'): assert name in base_src, f'base/processing.py must define {name}'
    ext_src = ext.read_text(encoding='utf-8')
    for name in ('def get_or_create_processing_account', 'def find_transfer_pairs', 'def create_transfer_out_entry', 'def create_transfer_in_entry', 'def get_processing_balance'): assert name in ext_src, f'extension/processing.py must define {name}'
    assert not (REPO / 'apps/backend/src/services/processing_account.py').exists(), 'services/processing_account.py must be deleted (folded into ledger, no shim)'
def test_ledger_base_layer_is_pure():
    offenders: dict[str, set[str]] = {}
    for path in sorted((LEDGER / 'base').rglob('*.py')):
        bad = {m for m in _imported_modules(path) if m.startswith('src.ledger.extension') or m.startswith('src.ledger.data') or 'sqlalchemy.ext.asyncio' in m or (m == 'src.database') or m.startswith('fastapi')}
        if bad: offenders[str(path.relative_to(LEDGER))] = bad
    assert not offenders, f'ledger base/ reaches into extension/data/ORM-session: {offenders}'
def test_ledger_anchored_persistence_boundary(): published = (LEDGER / '__init__.py').read_text(encoding='utf-8'); extension_published = (LEDGER / 'extension/__init__.py').read_text(encoding='utf-8'); anchor = (LEDGER / 'extension/anchored_posting.py').read_text(encoding='utf-8'); assert all((f'"{sink}"' not in published and f'"{sink}"' not in extension_published for sink in ('_create_anchored_journal_entry', '_create_anchored_journal_entries'))); imported_from_repository = {alias.name for node in ast.walk(ast.parse(anchor)) if isinstance(node, ast.ImportFrom) and node.module == 'src.ledger.extension.repository' for alias in node.names}; assert {'_create_anchored_journal_entry', '_create_anchored_journal_entries'} <= imported_from_repository; assert 'await validate_decision_anchor(' in anchor
def test_ledger_only_all_is_the_published_language(): import src.ledger as ledger_pkg; from common.ledger.contract import CONTRACT; assert sorted(CONTRACT.interface) == sorted(ledger_pkg.__all__); assert CONTRACT.name == 'ledger'; assert CONTRACT.klass == 'domain'; assert CONTRACT.implementations['be'] == 'apps/backend/src/ledger'
def test_ledger_package_contract_gate_passes(): names = {p.name for p in discover_packages(REPO)}; assert 'ledger' in names, f'ledger not discovered; found {names}'; ok, messages = check_single_package('ledger', REPO); assert ok, 'package contract gate failed:\n' + '\n'.join(messages)
